// ========================
// Current Part Logic
// ========================
let currentPart =
  getQueryParam("part") || Number(localStorage.getItem(STORAGE_KEY)) || 1;

if (currentPart < 1) currentPart = 1;
if (currentPart > parts.length) currentPart = parts.length;
const showFullTextBtn = document.getElementById("showAllTextBtn");

showAllTextBtn.addEventListener("click", () => {
  if (typeId) clearTimeout(typeId); // توقف تایمر تایپ
  const part = parts[currentPart - 1];
  if (!part) return;
  storyEl.innerHTML = ""; // پاک کردن متن قبلی
  const paragraphs = part.text.split("\n\n").filter(Boolean);
  paragraphs.forEach((pText) => {
    const p = document.createElement("p");
    p.className = "paragraph show";
    p.innerText = pText; // نمایش کل متن بدون تایپ
    storyEl.appendChild(p);
  });
});
