// Typewriter
// ========================
let typeId = null;
function startTypewriter(text) {
  if (typeId) clearTimeout(typeId);
  storyEl.innerHTML = "";
  const paragraphs = text.split("\n\n").filter(Boolean);
  let index = 0;

  function createParagraph() {
    if (index >= paragraphs.length) return;
    const p = document.createElement("p");
    p.className = "paragraph show";
    storyEl.appendChild(p);
    let i = 0;
    const current = paragraphs[index];

    function type() {
      if (i <= current.length) {
        p.innerHTML = current.substring(0, i);
        i++;
        typeId = setTimeout(type, 17);
      } else {
        index++;
        typeId = setTimeout(createParagraph, 300);
      }
    }
    type();
  }
  createParagraph();
}

// ========================
// Music
// ========================

function fadeToMusic(src) {
  if (music.src.endsWith(src)) {
    // موزیک همون قبلیه، کاری نکن
    return;
  }

  if (!music.paused) {
    // Fade out و بعد play
    let volume = music.volume;
    const fadeOut = setInterval(() => {
      volume -= 0.05;
      if (volume <= 0) {
        clearInterval(fadeOut);
        music.pause();
        music.src = src;
        music.load();
        music.volume = 0;
        music.play().catch(() => {});
        let fadeInVolume = 0;
        const fadeIn = setInterval(() => {
          fadeInVolume += 0.05;
          music.volume = Math.min(fadeInVolume, 1);
          if (fadeInVolume >= 1) clearInterval(fadeIn);
        }, 50);
      }
      music.volume = Math.max(volume, 0);
    }, 50);
  } else {
    // فقط src عوض میشه، پلی نکن
    music.src = src;
  }
}

musicBtn.addEventListener("click", () => {
  if (music.paused) {
    music.play();
    musicBtn.innerHTML = "🎵";
    musicBtn.classList.add("playing");
  } else {
    music.pause();
    musicBtn.innerHTML = "🎧";
    musicBtn.classList.remove("playing");
  }
});

// ========================
// Navigation Helpers
// ========================
function saveProgress() {
  const saved = Number(localStorage.getItem(STORAGE_KEY)) || 0;
  if (currentPart > saved) {
    localStorage.setItem(STORAGE_KEY, currentPart);
  }
}

function updateButtons() {
  prevBtn.disabled = currentPart <= 1;
  nextBtn.disabled = currentPart >= parts.length;
}

function renderPart() {
  const part = parts[currentPart - 1];
  if (!part) return;
  chapterTitle.innerText = part.title;
  startTypewriter(part.text);
  fadeToMusic(part.music);
  updateButtons();
  saveProgress();
}

function goToPart(newPart) {
  if (newPart < 1 || newPart > parts.length) return;
  overlayTitle.innerText = parts[newPart - 1].title;
  overlay.classList.add("active");
  setTimeout(() => {
    currentPart = newPart;
    renderPart();
  }, 400);
  setTimeout(() => overlay.classList.remove("active"), 1000);
}

// ========================
// Event Listeners
// ========================
prevBtn.addEventListener("click", () => goToPart(currentPart - 1));
nextBtn.addEventListener("click", () => goToPart(currentPart + 1));
backBtn.addEventListener("click", () => window.history.back());

// ========================
// Init
// ========================
document.addEventListener("DOMContentLoaded", () => {
  renderPart();
});
